 if($('rm'))$('rm').onclick=function(){BA.box('<h3>Return to Maker</h3><p>Send this notice back for re-extraction. Maker will retry or flag it for the source team.</p><div class="form" style="max-width:none"><label>Reason<select id="rr"><option>Source document is unreadable</option><option>Notice appears withdrawn or cancelled</option><option>Wrong property or duplicate property</option><option>Other</option></select></label><label>Note to Maker<textarea id="rn"></textarea></label><button class="btn" id="rgo">Return to Maker</button></div>');$('rgo').onclick=function(){status='returned';audit.push({what:'Returned to Maker: '+$('rr').value+($('rn').value?' ('+$('rn').value+')':''),who:staff.name,when:when()});persist();location.href='checker.html'}};
